42	func (s *Store) UpsertUserSetting(ctx context.Context, upsert *storepb.UserSetting) (*storepb.UserSetting, error) {
43		userSettingRaw, err := convertUserSettingToRaw(upsert)
44		if err != nil {
45			return nil, err
46		}
47		userSettingRaw, err = s.driver.UpsertUserSetting(ctx, userSettingRaw)
48		if err != nil {
49			return nil, err
50		}
51	
52		userSetting, err := convertUserSettingFromRaw(userSettingRaw)
53		if err != nil {
54			return nil, err
55		}
56		if userSetting == nil {
57			return nil, errors.New("unexpected nil user setting")
58		}
59		s.userSettingCache.Set(ctx, getUserSettingCacheKey(userSetting.UserId, userSetting.Key.String()), userSetting)
60		return userSetting, nil
61	}
